import { useState } from 'react';
import {
  JxStack,
  JxStepper,
  JxStep,
  JxCard,
  JxHeading,
  JxText,
  JxInput,
  JxButton,
  JxDivider,
} from '@jinx-ui/react';

interface RegistrationData {
  fullName: string;
  email: string;
  phone: string;
  country: string;
  city: string;
  street: string;
  postalCode: string;
}

interface RegistrationWizardProps {
  onSubmit: (data: RegistrationData) => void;
}

const STEPS = ['Контакты', 'Адрес', 'Проверка'] as const;

const INITIAL_DATA: RegistrationData = {
  fullName: '',
  email: '',
  phone: '',
  country: '',
  city: '',
  street: '',
  postalCode: '',
};

export default function RegistrationWizard({ onSubmit }: RegistrationWizardProps) {
  const [currentStep, setCurrentStep] = useState(0);
  const [data, setData] = useState<RegistrationData>(INITIAL_DATA);

  const updateField = (field: keyof RegistrationData) => (value: string) => {
    setData((prev) => ({ ...prev, [field]: value }));
  };

  const isLastStep = currentStep === STEPS.length - 1;
  const isFirstStep = currentStep === 0;

  const goNext = () => {
    if (!isLastStep) {
      setCurrentStep((step) => step + 1);
    }
  };

  const goBack = () => {
    if (!isFirstStep) {
      setCurrentStep((step) => step - 1);
    }
  };

  const handleSubmit = () => {
    onSubmit(data);
  };

  return (
    <JxCard className="jx-p-6" style={{ maxWidth: 'var(--jx-size-md, 480px)' }}>
      <JxStack direction="column" gap="lg">
        <JxStepper activeStep={currentStep}>
          {STEPS.map((label) => (
            <JxStep key={label} label={label} />
          ))}
        </JxStepper>

        <JxDivider />

        {currentStep === 0 && (
          <JxStack direction="column" gap="md">
            <JxHeading level={3}>Контакты</JxHeading>
            <JxInput
              label="Полное имя"
              value={data.fullName}
              onChange={updateField('fullName')}
              placeholder="Иван Иванов"
            />
            <JxInput
              label="Email"
              type="email"
              value={data.email}
              onChange={updateField('email')}
              placeholder="you@example.com"
            />
            <JxInput
              label="Телефон"
              type="tel"
              value={data.phone}
              onChange={updateField('phone')}
              placeholder="+7 900 000-00-00"
            />
          </JxStack>
        )}

        {currentStep === 1 && (
          <JxStack direction="column" gap="md">
            <JxHeading level={3}>Адрес</JxHeading>
            <JxInput
              label="Страна"
              value={data.country}
              onChange={updateField('country')}
              placeholder="Россия"
            />
            <JxInput
              label="Город"
              value={data.city}
              onChange={updateField('city')}
              placeholder="Москва"
            />
            <JxInput
              label="Улица и дом"
              value={data.street}
              onChange={updateField('street')}
              placeholder="ул. Ленина, 1"
            />
            <JxInput
              label="Почтовый индекс"
              value={data.postalCode}
              onChange={updateField('postalCode')}
              placeholder="101000"
            />
          </JxStack>
        )}

        {currentStep === 2 && (
          <JxStack direction="column" gap="md">
            <JxHeading level={3}>Проверка</JxHeading>
            <JxText style={{ color: 'var(--jx-color-text-secondary)' }}>
              Проверьте введённые данные перед отправкой.
            </JxText>

            <JxStack direction="column" gap="xs">
              <JxText weight="bold">Контакты</JxText>
              <JxText>{data.fullName || '—'}</JxText>
              <JxText>{data.email || '—'}</JxText>
              <JxText>{data.phone || '—'}</JxText>
            </JxStack>

            <JxDivider />

            <JxStack direction="column" gap="xs">
              <JxText weight="bold">Адрес</JxText>
              <JxText>
                {[data.country, data.city, data.street, data.postalCode]
                  .filter(Boolean)
                  .join(', ') || '—'}
              </JxText>
            </JxStack>
          </JxStack>
        )}

        <JxDivider />

        <JxStack direction="row" justify="space-between">
          <JxButton variant="secondary" onClick={goBack} disabled={isFirstStep}>
            Назад
          </JxButton>

          {isLastStep ? (
            <JxButton variant="primary" onClick={handleSubmit}>
              Отправить
            </JxButton>
          ) : (
            <JxButton variant="primary" onClick={goNext}>
              Дальше
            </JxButton>
          )}
        </JxStack>
      </JxStack>
    </JxCard>
  );
}

